<?php
use EIPSI\ExternalApi as A;
function d2_wait($path){$deadline=microtime(true)+20;while(!file_exists($path)){if(microtime(true)>$deadline)throw new RuntimeException('API2A barrier timed out');usleep(10000);}}
function d2_spawn($input){$dir='/tmp/eipsi-api2a-'.bin2hex(random_bytes(8));mkdir($dir,0700);$pipes=array();$p=proc_open(array(PHP_BINARY,__DIR__.'/worker.php',$dir),array(0=>array('pipe','r'),1=>array('file',$dir.'/stdout','w'),2=>array('file',$dir.'/stderr','w')),$pipes);d2_assert(is_resource($p));fwrite($pipes[0],json_encode($input));fclose($pipes[0]);d2_wait($dir.'/attempt');return array('process'=>$p,'dir'=>$dir);}
function d2_join(&$job){d2_wait($job['dir'].'/result.json');$r=json_decode(file_get_contents($job['dir'].'/result.json'),true);d2_assert(proc_close($job['process'])===0);$job['process']=null;return$r;}
function d2_remove($job){if(!$job)return;if(is_resource($job['process']))proc_terminate($job['process']);foreach(glob($job['dir'].'/*')as$f)unlink($f);rmdir($job['dir']);}
d2_case('Concurrent data request observes revocation committed before authorization',function()use($store){$k=d2_key();$job=null;try{$store->transaction(function()use($store,$k,&$job){$store->key($k['key']['id'],true);$job=d2_spawn(array('op'=>'data','secret'=>$k['secret'],'code'=>$GLOBALS['p']['public']));usleep(100000);d2_assert(!file_exists($job['dir'].'/result.json'));$store->rows($store->prepare('UPDATE '.$store->table('keys').' SET revoked_at=%d,revision=revision+1 WHERE id=%s',time(),$k['key']['id']));});$r=d2_join($job);d2_assert($r['status']===401);}finally{d2_remove($job);}});
d2_case('Concurrent hard delete preserves an earlier coherent read and later returns 404',function()use($store,$wpdb){$p=d2_publish();d2_finish($p);$k=d2_key(array($p['definition']['study']['logical_id']));$del=null;$read=null;try{$store->transaction(function()use($store,$p,$k,&$del,&$read,$wpdb){$store->row($store->prepare('SELECT id FROM `'.$wpdb->prefix.'eipsi_engine_study_versions` WHERE id=%s FOR UPDATE',$p['version']));$del=d2_spawn(array('op'=>'delete','study'=>$p['definition']['study']['logical_id']));usleep(100000);d2_assert(!file_exists($del['dir'].'/result.json'));$read=d2_spawn(array('op'=>'data','secret'=>$k['secret'],'code'=>$p['public']));$r=d2_join($read);d2_assert($r['status']===200&&count($r['data']['items'])===1);});d2_assert(d2_join($del)['status']===200);d2_error(function()use($k,$p){d2_read($k,array(),$p);},404,'eipsi_external_study_unavailable');}finally{d2_remove($read);d2_remove($del);}});
d2_case('Data request already started cannot bypass a privacy change committed before its snapshot',function(){ $p=d2_publish(true);$f=d2_finish($p,'PRIVACY_RACE_SECRET');$k=d2_key(array($p['definition']['study']['logical_id']));$job=null;try{$job=d2_spawn(array('op'=>'data','secret'=>$k['secret'],'code'=>$p['public'],'wait'=>true));d2_assert(!file_exists($job['dir'].'/result.json'));d2_withdraw($f['frame'],'DO_NOT_USE');touch($job['dir'].'/release');$r=d2_join($job);d2_assert($r['status']===200&&$r['data']['items']===array());}finally{d2_remove($job);}});
